{"content": "from decimal import Decimal
from typing import List

from pydantic import BaseModel


class PricePoint(BaseModel):
    sku: str
    price: Decimal
    discount: Decimal = Decimal("0")


class PriceList(BaseModel):
    currency: str
    points: List[PricePoint]


def price_list_json(pl: PriceList) -> str:
    # Pydantic v2: `.json()` is deprecated in favor of `.model_dump_json()`.
    # Note: v2 serializes Decimal as a JSON string (e.g. "9.99"), whereas v1
    # emitted a JSON number. Update consumers if they expect numbers.
    return pl.model_dump_json()
